```svelte
<script>
	import { $state } from 'svelte';

	const books = $state([
		'The Lord of the Rings',
		'To Kill a Mockingbird',
		'1984'
	]);

	function title({ children }: { children: string }) {
		<span data-testid="book-title">{children}</span>;
	}
</script>

<ul>
	{#each books as book}
		<li data-testid="book-item">
			{@render title({ children: book })}
		</li>
	{/each}
</ul>
